cat > /tmp/ParseBinlog/Program.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== BUILD RESULT: " + (build.Succeeded ? "SUCCESS" : "FAILED") + " ===\n");

// Collect all errors and warnings
var errors = new List<(string project, string file, int line, int col, string code, string message, string subcategory)>();
var warnings = new List<(string project, string file, int line, int col, string code, string message)>();

void Walk(BaseNode node, string currentProject = "")
{
    if (node is Project p) currentProject = p.Name ?? currentProject;
    if (node is Error e)
    {
        errors.Add((currentProject, e.File ?? "", e.LineNumber, e.ColumnNumber, e.Code ?? "", e.Text ?? e.ToString(), e.Subcategory ?? ""));
    }
    if (node is Warning w)
    {
        warnings.Add((currentProject, w.File ?? "", w.LineNumber, w.ColumnNumber, w.Code ?? "", w.Text ?? w.ToString()));
    }
    if (node is TreeNode tn)
    {
        foreach (var child in tn.Children)
        {
            if (child is BaseNode bn) Walk(bn, currentProject);
        }
    }
}

Walk(build);

Console.WriteLine($"Total errors: {errors.Count}");
Console.WriteLine($"Total warnings: {warnings.Count}\n");

Console.WriteLine("=== ERRORS ===");
foreach (var e in errors)
{
    Console.WriteLine($"[{e.project}] {e.code}: {e.message}");
    if (!string.IsNullOrEmpty(e.file))
        Console.WriteLine($"  File: {e.file}:{e.line}:{e.col}");
    Console.WriteLine();
}

Console.WriteLine("=== WARNINGS ===");
foreach (var w in warnings)
{
    Console.WriteLine($"[{w.project}] {w.code}: {w.message}");
    if (!string.IsNullOrEmpty(w.file))
        Console.WriteLine($"  File: {w.file}:{w.line}:{w.col}");
    Console.WriteLine();
}

// Show project dependency info and which projects failed
Console.WriteLine("=== PROJECT BUILD STATUS ===");
void WalkProjects(BaseNode node, int depth = 0)
{
    if (node is Project proj)
    {
        var hasErrors = false;
        void CheckErrors(BaseNode n) {
            if (n is Error) hasErrors = true;
            if (n is TreeNode t) foreach (var c in t.Children) { if (c is BaseNode b) CheckErrors(b); }
        }
        CheckErrors(proj);
        if (hasErrors || !proj.Succeeded)
            Console.WriteLine($"  FAILED: {proj.Name} (Target: {proj.TargetFramework})");
    }
    if (node is TreeNode tn)
    {
        foreach (var child in tn.Children)
        {
            if (child is BaseNode bn) WalkProjects(bn, depth + 1);
        }
    }
}
WalkProjects(build);
