using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Find PackageReference items per project
var projPackages = new Dictionary<string, HashSet<string>>();
var projRefs = new Dictionary<string, HashSet<string>>();

void Walk(BaseNode node, string proj = "")
{
    if (node is Project p) proj = p.Name ?? proj;
    if (!string.IsNullOrEmpty(proj) && node is AddItem ai)
    {
        if (ai.Name == "PackageReference")
        {
            if (!projPackages.ContainsKey(proj)) projPackages[proj] = new HashSet<string>();
            foreach (var child in ai.Children)
                if (child is Item item) projPackages[proj].Add(item.Text);
        }
        if (ai.Name == "ProjectReference")
        {
            if (!projRefs.ContainsKey(proj)) projRefs[proj] = new HashSet<string>();
            foreach (var child in ai.Children)
                if (child is Item item) projRefs[proj].Add(item.Text);
        }
    }
    if (node is TreeNode tn)
        foreach (var child in tn.Children)
            if (child is BaseNode bn) Walk(bn, proj);
}
Walk(build);

Console.WriteLine("=== PACKAGE REFERENCES PER PROJECT ===");
foreach (var kv in projPackages)
{
    Console.WriteLine($"\n  {kv.Key}:");
    foreach (var pkg in kv.Value)
        Console.WriteLine($"    - {pkg}");
}

Console.WriteLine("\n=== PROJECT REFERENCES PER PROJECT ===");
foreach (var kv in projRefs)
{
    Console.WriteLine($"\n  {kv.Key}:");
    foreach (var r in kv.Value)
        Console.WriteLine($"    - {r}");
}
