cat > /tmp/ParseBinlog/Program.cs << 'CSHARP'
using System;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Search entire tree for anything mentioning Newtonsoft
void WalkAll(BaseNode node, string path = "", int depth = 0)
{
    var s = node.ToString() ?? "";
    if (s.Contains("Newtonsoft", StringComparison.OrdinalIgnoreCase))
    {
        Console.WriteLine($"[depth={depth}] {node.GetType().Name}: {(s.Length > 300 ? s.Substring(0, 300) : s)}");
        Console.WriteLine($"  Path: {path}");
    }
    if (node is TreeNode tn)
        foreach (var child in tn.Children)
            if (child is BaseNode bn) WalkAll(bn, path + "/" + node.GetType().Name, depth + 1);
}
WalkAll(build);

// Also find what compile items Services has
Console.WriteLine("\n=== COMPILE ITEMS FOR Services ===");
void WalkCompile(BaseNode node, string proj = "")
{
    if (node is Project p) proj = p.Name ?? proj;
    if (proj == "Services.csproj" && node is AddItem ai && ai.Name == "Compile")
    {
        foreach (var child in ai.Children)
            if (child is Item item) Console.WriteLine($"  {item.Text}");
    }
    if (node is TreeNode tn)
        foreach (var child in tn.Children)
            if (child is BaseNode bn) WalkCompile(bn, proj);
}
WalkCompile(build);
